namespace AIVoiceActing.Domain;

using System.Text.Json;
using AIVoiceActing.Ports;

/// <summary>
/// The stock Kokoro bank described as library data: the embedded <c>voices-core.json</c>
/// (generated by <c>tools/voicepack/gen_core_manifest.py</c> from the same prefix rules as
/// <see cref="VoiceCatalog"/>). Ids are the bank's own and never change. Stock voices have no
/// file of their own: the engine finds them by id in its voice bank, so their realization
/// path is empty and they are always available.
/// </summary>
public static class CoreVoiceManifest
{
    public const string ResourceName = "voices-core.json";

    private static readonly JsonSerializerOptions JsonOptions = new() { PropertyNameCaseInsensitive = true };

    private sealed record CoreFile(
        string PackId,
        string PackName,
        string Version,
        string License,
        string? Attribution,
        List<CoreVoice> Voices);

    private sealed record CoreVoice(
        string Id,
        string Name,
        string Accent,
        string Sex,
        string? Description,
        List<string>? Tags);

    /// <summary>The embedded manifest as a pack plus its voices.</summary>
    public static (VoicePackInfo Pack, IReadOnlyList<VoiceInfo> Voices) Load()
    {
        using var stream = typeof(CoreVoiceManifest).Assembly.GetManifestResourceStream(ResourceName)
            ?? throw new InvalidOperationException($"Embedded resource \"{ResourceName}\" is missing.");
        using var reader = new StreamReader(stream);
        return Parse(reader.ReadToEnd());
    }

    public static (VoicePackInfo Pack, IReadOnlyList<VoiceInfo> Voices) Parse(string json)
    {
        var file = JsonSerializer.Deserialize<CoreFile>(json, JsonOptions)
            ?? throw new InvalidOperationException("voices-core.json deserialized to null.");

        var voices = file.Voices.Select(voice => new VoiceInfo(
            voice.Id,
            voice.Name,
            voice.Accent,
            voice.Sex,
            AgeBand: "adult",
            voice.Description ?? string.Empty,
            file.License,
            file.Attribution,
            voice.Tags ?? [],
            VoiceQuality.Stock,
            PreviewFile: null,
            file.PackId,
            [new VoiceRealization(
                RealizationKind.StyleTensor,
                VoicePackManifest.KokoroEngine,
                Path: string.Empty,
                Phonemizers.ForKokoroId(voice.Id),
                Transcript: null)])).ToList();

        var pack = new VoicePackInfo(
            file.PackId, file.PackName, file.Version, file.License, Bytes: 0, voices.Count,
            Enabled: true, Problems: [], Directory: string.Empty);
        return (pack, voices);
    }
}
